package dev.veltraph.client.mining.vein;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class VeinAdmissionTransactionTest {
 @Test void identityPreparationCostCannotExtendOverallDeadline(){var t=new VeinAdmissionTransaction("scope",100,10000000);assertTrue(t.probe(10001000,1));assertFalse(t.commit("scope",100,true,true));}
 @Test void partialGeometryCannotCommit(){var t=new VeinAdmissionTransaction("scope",100,0);assertFalse(t.probe(4000001,1));assertFalse(t.commit("scope",10,true,true));}
 @Test void queryCountCannotBeResetInsideTransaction(){var t=new VeinAdmissionTransaction("scope",100,0);assertFalse(t.probe(1,4097));assertTrue(t.probe(2,1));assertFalse(t.commit("scope",10,true,true));}
 @Test void freshScopeAndFullIdentityRemainMandatory(){var t=new VeinAdmissionTransaction("scope",100,0);assertTrue(t.probe(1000,5));assertFalse(t.commit("foreign",10,true,true));assertFalse(t.commit("scope",10,true,false));assertTrue(t.commit("scope",10,true,true));assertFalse(t.commit("scope",10,true,true));}
 @Test void slowFreshScopeCallbackExpiresGeometryBeforeCommit(){var t=new VeinAdmissionTransaction("scope",100,0);assertTrue(t.probe(1000,3));assertFalse(t.commitFresh("scope",4000001,3,10,true,true));}
 @Test void finalReadAfterScopeChangeCannotUseEarlierClockSample(){var t=new VeinAdmissionTransaction("scope",100,0);assertTrue(t.probe(1000,3));assertFalse(t.commitFresh("foreign",2000,3,10,true,true));}
 @Test void completedScopeWithinBudgetCanCommitOnce(){var t=new VeinAdmissionTransaction("scope",100,0);assertTrue(t.commitFresh("scope",4000000,7,10,true,true));assertFalse(t.commitFresh("scope",4000000,7,10,true,true));}
 @Test void slotPublicationReentryCannotRetainOldCameraOrPose(){Object p=new Object(),w=new Object(),c=new Object(),owner=new Object(),camera=new Object();var expected=new VeinAdmissionTransaction.Publication(p,w,c,owner,camera,3,"pose",10,20,"cfg","components",1,2);assertTrue(VeinAdmissionTransaction.unchangedPublication(expected,expected));assertFalse(VeinAdmissionTransaction.unchangedPublication(expected,new VeinAdmissionTransaction.Publication(p,w,c,new Object(),camera,3,"pose",10,20,"cfg","components",1,2)));assertFalse(VeinAdmissionTransaction.unchangedPublication(expected,new VeinAdmissionTransaction.Publication(p,w,c,owner,camera,4,"pose",10,20,"cfg","components",1,2)));assertFalse(VeinAdmissionTransaction.unchangedPublication(expected,new VeinAdmissionTransaction.Publication(p,w,c,owner,camera,3,"moved",10,20,"cfg","components",1,2)));assertFalse(VeinAdmissionTransaction.unchangedPublication(expected,new VeinAdmissionTransaction.Publication(p,w,c,owner,camera,3,"pose",11,20,"cfg","components",1,2)));}
 @Test void reentrantConfigurationMutationIsSeenByNativeLeaves(){Object p=new Object(),w=new Object(),c=new Object(),owner=new Object(),camera=new Object();var epoch=new java.util.concurrent.atomic.AtomicLong(3);var order=new java.util.ArrayList<String>();var captured=VeinAdmissionTransaction.capturePublication(new VeinAdmissionTransaction.PublicationPort(){public Object configuration(){order.add("config");epoch.set(4);return "cfg";}public Object owner(){order.add("owner");return owner;}public Object camera(){order.add("camera");return camera;}public VeinAdmissionTransaction.Publication nativeLeaves(Object cfg,Object own,Object cam){order.add("native");return new VeinAdmissionTransaction.Publication(p,w,c,own,cam,epoch.get(),"pose",10,20,cfg,"components",1,2);}});assertEquals(java.util.List.of("config","owner","camera","native"),order);assertEquals(4,captured.epoch());var earlier=new VeinAdmissionTransaction.Publication(p,w,c,owner,camera,3,"pose",10,20,"cfg","components",1,2);assertFalse(VeinAdmissionTransaction.unchangedPublication(earlier,captured));}
 @Test void admissionScopeConsumesCapturedPublicationWithoutAnotherSelectorRead(){Object p=new Object(),w=new Object(),c=new Object(),o=new Object(),cam=new Object();var reads=new java.util.concurrent.atomic.AtomicInteger();var captured=VeinAdmissionTransaction.capturePublication(new VeinAdmissionTransaction.PublicationPort(){public Object configuration(){reads.incrementAndGet();return "cfg";}public Object owner(){reads.incrementAndGet();return o;}public Object camera(){reads.incrementAndGet();return cam;}public VeinAdmissionTransaction.Publication nativeLeaves(Object cfg,Object own,Object camera){return new VeinAdmissionTransaction.Publication(p,w,c,own,camera,3,"pose",10,20,cfg,"components",1,2);}});var scope=VeinAdmissionTransaction.admissionScope(captured,"tool",1);assertEquals(3,reads.get());assertSame(cam,scope.cameraOwner());assertSame(o,scope.owner());assertSame(p,scope.player());assertEquals(2,scope.slot());}
}
